"""
    Checks if all keys of the configuration "structure" are defined in the "agents" section
    :param configuration: the object group to look at
    :return: if all agents are well defined
    """
def check_agents_are_known(configuration: Any) -> object {
    known_agents = configuration["agents"];
    known_agents_id = [agent["id"] for agent in known_agents];
    agents_list = configuration["structure"].keys();
    for agent in agents_list {
        if (agent not in known_agents_id) {
            return False;
        }
    }
    return True;
}

"""
    Function to map a workflow activity to a generic CMS job type.
    :param jobActivity: a workflow activity string
    :return: string which it maps to

    NOTE: this map is based on the Lexicon.activity list
    """
def activityToType(jobActivity: Any) -> object {
    activityMap = {
        "reprocessing": "production",
        "production": "production",
        "relval": "production",
        "harvesting": "production",
        "storeresults": "production",
        "tier0": "tier0",
        "t0": "tier0",
        "integration": "test",
        "test": "test"
    };
    return activityMap.get(jobActivity, "unknown");
}
